INSERT INTO feature VALUES('rust-default-layout','layouts','Rust''s default layout as a program',NULL,'partial','uncommon','mainstream languages','rustc''s layout of a `repr(Rust)` type is a gandr program over the type''s code, `std.layout`, after `rustc_abi`''s `univariant` and `layout_of_enum`: a struct''s fields sorted by alignment, its niche toward the start or, when that leaves the niche nearer the middle, the end; an enum''s niche-filled and tagged layouts, the tag widened to the smallest first-field alignment, the smaller kept, then the larger niche, then the tagged. Checked against `rustc -Zprint-type-sizes` on eleven structs and enums over unsigned and signed integer, `bool` and reference fields, it agrees on every size, alignment, offset and discriminant; rustc stays the authority on a Rust type''s layout. A field that is itself an aggregate waits for levitated codes (#2343), and a niche beyond `bool`''s and a reference''s needs a theory of the target.',NULL,'library/std/src/layout.gandr corpus/model/layouts/rust-default.gandr corpus/pathological/layouts/rust-default.gandr','corpus/ledger/features/rust-default-layout.gandr','#2343');
